export const FALLBACK_PREFERENCES: TerminalPreferences = {
  fontFamily: DEFAULT_TERMINAL_FONT_STACK,
  fontSize: 13,
  macosOptionAsAlt: false,
  cursorStyle: "block",
  theme: DEFAULT_TERMINAL_THEME,
  source: "defaults",
