/**
 * Batches incoming PTY output chunks per terminal renderer at animation-frame cadence.
 *
 * Queue policy:
 * - Chunks received between rAF flushes are held in an ordered per-renderer buffer.
 * - On frame flush, all buffered chunks coalesce into a single `terminal.write` call in original arrival order.
 * - Replay backlog delivered synchronously during `subscribeOutput` is enqueued before subsequent live output.
 * - Teardown (via unlisten or manager destroy) immediately cancels pending rAF callbacks and clears buffered data,
 *   preventing stale or out-of-order writes after session rebinding or instance disposal.
 */
function attachScheduledOutputSubscription(
  backendSessionId: string,
  terminal: Terminal,
): () => void {
  let outputBuffer: string[] = [];
  let outputFrame = 0;

  const flushOutput = () => {
    outputFrame = 0;
    if (outputBuffer.length === 0) return;
    const coalesced = outputBuffer.length === 1 ? outputBuffer[0]! : outputBuffer.join("");
    outputBuffer = [];
    terminal.write(coalesced);
  };

  const unsubscribe = terminalEventBus.subscribeOutput(backendSessionId, (text) => {
    outputBuffer.push(text);
    if (outputFrame === 0) {
      outputFrame = requestAnimationFrame(flushOutput);
    }
  });

  return () => {
    if (outputFrame !== 0) {
      cancelAnimationFrame(outputFrame);
      outputFrame = 0;
    }
    outputBuffer = [];
    unsubscribe();
  };
}

class TerminalHostManager {

let unsubscribeOutput: (() => void) | undefined;
if (session.backendSessionId) {
  unsubscribeOutput = attachScheduledOutputSubscription(session.backendSessionId, terminal);
}

